ne;"><img src="/assets/img/e05ca2873721-05.avif" width="412" height="512" class="image-carousel__image" alt="" loading="lazy" style="display:none;"><img src="/assets/img/c5dac772c117-06.avif" width="412" height="512" class="image-carousel__image" alt="" loading="lazy" style="display:none;"><!--]--></div><div class="carousel-autoplay carousel-autoplay--paused image-carousel__controls" style="--autoplay-item-duration:5000ms;"><button class="carousel-autoplay__button" aria-label="Play carousel"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40"><g><path fill="currentColor" d="M16 14.741a1 1 0 0 1 1.504-.864l9.015 5.26a1 1 0 0 1 0 1.727l-9.015 5.259A1 1 0 0 1 16 25.259z"></path></g></svg></button><div class="carousel-autoplay__dots"><!--[--><button class="carousel-autoplay__dot--active carousel-autoplay__dot" aria-label="Go to slide 1"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 2"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 3"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 4"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 5"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 6"></button><!--]--></div></div></div><!--]--></div><div class="image-info-box__item image-info-box__item--main"><div class="scroll-box"><div class="vertical-scroll-progress-bar vertical-scroll-progress-bar--theme-primary scroll-box__progress-bar"></div><div class="scroll-box__header"><p class="u-text-body-large">In our care, youâ€™ll receive not only treatment and a perfect smile, but also care, openness and support all the way to the result. Our mission is to change the perception of dentistry. </p><!----></div><div class="scroll-box__body"><!--[--><!--[--><div class="u-wysiwyg"><p>Music, ambiance and a finely designed interior together with a specially tailored atmosphere will enable you to experience a completely different dentistry — one that is comfortable, calm and inspiring.</p>
<p>We want your experience with us to be like flying in first class — personal, convenient and with no worries or stress.</p>
</div><!--]--><!--]--></div></div></div><!----></div><!--]--></div></div><!--]--></div><div class="overlay-section"><!--[--><div class="about-experience u-bg-primary"><div class="wheel-block"><div class="wheel-block__sticky-content"><div class="wheel-block__header"><div class="container container--size-default"><!--[--><h2 class="section-title u-text-headings-large"><!--[-->Your smile <span class="u-text-wine">starts here</span><!--]--></h2><!--]--></div></div><div class="wheel-block__body"><div class="wheel-block__body-inner"><div class="container container--size-default"><!--[--><div class="wheel-block-wheel"><svg xmlns="http://www.w3.org/2000/svg" width="1202" height="1202" viewBox="0 0 1202 1202" fill="none" class="wheel-block-wheel__svg" style="--wheel-rotation-degrees-start:60deg;"><circle cx="600" cy="600" r="534.5" stroke="#DDEFDE" opacity=".2"></circle><!--[--><g class="wheel-step" transform="rotate(0 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">1</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(60 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">2</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(120 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">3</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(180 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">4</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(240 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">5</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(300 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">6</text><path class="wheel-step__line" d="M601 90v116"></path></g><!--]--></svg><!--[--><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">More personal than personal</h3><p class="u-text-body-medium wheel-block-wheel__item-description">After a complex diagnosis, each patient is assigned a Treatment Plan Coordinator, or Personal Concierge. He or she takes care to ensure that the entire process is flawless and personalised — from scheduling appointments to the tiniest details that make your experience enjoyable and give you peace of mind.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">A result you can see in advance</h3><p class="u-text-body-medium wheel-block-wheel__item-description">We create a 3D digital smile design before treatment even starts. Not only do you know what the end result will be, but you can see it, influence it, and feel confident about every next step.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Peace and safety during every appointment</h3><p class="u-text-body-medium wheel-block-wheel__item-description">We believe that treatment starts with a feeling. The light, interior design, silence and the attitude of our team create an environment in which you can relieve stress and forget any previous perceptions of dentistry as an unpleasant experience.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Movie experience in a dentistâ€™s chair</h3><p class="u-text-body-medium wheel-block-wheel__item-description">We transform time in the dentistâ€™s chair into a pleasurable experience — choose your favourite movie, TV series or educational content and let the treatment flow seamlessly.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">All in one place</h3><p class="u-text-body-medium wheel-block-wheel__item-description">What matters to us is that you save not only money, but also time and energy. Thatâ€™s why all the relevant specialists — therapists, prosthodontists, endodontist, implantologists, aestheticians and hygienists are all here under one roof at LAVA dental. This means a faster, more precise and more efficient treatment process.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Complete privacy</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Treatment takes place in quiet, enclosed premises. Here you can feel safe, free and comfortable, away from the gaze of others or any disturbance.</p></div><!--]--></div><!--]--></div></div></div></div><div class="wheel-block__triggers"><!--[--><div data-nr="1" class="wheel-block__trigger"></div><div data-nr="2" class="wheel-block__trigger"></div><div data-nr="3" class="wheel-block__trigger"></div><div data-nr="4" class="wheel-block__trigger"></div><div data-nr="5" class="wheel-block__trigger"></div><div data-nr="6" class="wheel-block__trigger"></div><!--]--></div></div></div><!--]--></div><div class="overlay-section"><!--[--><div class="reveal-block about-apply"><div class="reveal-block__content"><div class="reveal-block__header u-bg-secondary"><div class="container container--size-default"><!--[--><p class="reveal-block__title u-text-headings-large"><span class="word" aria-hidden="true" style="display: inline-block;">Thatâ€™s</span> <span class="word" aria-hidden="true" style="display: inline-block;">us</span> <span class="word" aria-hidden="true" style="display: inline-block;">—</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">LAVA</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">dental</span> <span class="word u-text-wine" aria-hidden="true" style="display: inline-block;">studio.</span><span class="sr-only" style="position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px;">Thatâ€™s us — LAVA dental studio.</span></p><!--]--></div></div><div class="u-bg-primary reveal-block__body" style=""><div class="reveal-block__bg"><canvas class="lava-bg-illustration reveal-block__bg-illustration" width="1920" height="1230"></canvas><div class="container container--size-default"><!--[--><p class="reveal-block__title reveal-block__title--bg u-text-headings-large"><span class="u-text-white">Thatâ€™s us -</span> <span class="u-text-gold">LAVA dental studio.</span></p><!--]--></div></div><div class="container container--size-default"><!--[--><div class="reveal-block__main-wrap"><div class="reveal-block__main"><!--[--><div class="about-apply-grid"><div class="about-apply-grid__item about-apply-box u-bg-secondary"><div class="about-apply-box__aside"><div class="video-dialog video-dialog--type-cover about-apply-box__preview"><video class="video-dialog__preview" width="300" height="534" muted="" loop="" playsinline="" src="/cms/api/media/file/about-preview.webm" autoplay=""></video><button aria-label="Play video" class="video-dialog__button"><div class="icon-button icon-button--type-primary icon-button--size-medium video-dialog__play-button"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="54" height="54" viewBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div></div></button><!--teleport start--><!--teleport end--></div></div><div class="about-apply-box__body"><p class="u-text-headings-small">Make an appointment and step towards your perfect smile!</p><a class="button button--type-secondary button--icon-end about-apply-box__cta-button" href="https://booking.lavadental.lv/en" target="_blank"><div class="button__text u-text-body-button"><!--[-->Make an appointment<!--]--></div><!----></a></div></div></div><!--]--></div></div><!--]--></div></div></div><div class="reveal-block__timeline"><div class="reveal-block__timeline-item reveal-block__timeline-item--intro"></div><div class="reveal-block__timeline-item reveal-block__timeline-item--main"></div></div></div><!--]--></div></section>
