mage service-card__image" alt="implants" loading="lazy" src="/cms/api/media/file/Implants-600x820.avif"><div class="service-card__content"><div class="service-card__header"><div class="service-card__nr u-text-body-large">04</div><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-card__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div><div class="service-card__body"><h3 class="service-card__title u-text-headings-small">Dental implants</h3></div></div></div><div class="services-card-grid__item service-card u-bg-primary" style="--delay:1.2s;"><img width="600" height="820" data-nuxt-img="" srcset="/cms/api/media/file/Aligners-600x820.avif 1x, /cms/api/media/file/Aligners-600x820.avif 2x" onerror="this.setAttribute('data-error', 1)" class="image service-card__image" alt="aligners" loading="lazy" src="/cms/api/media/file/Aligners-600x820.avif"><div class="service-card__content"><div class="service-card__header"><div class="service-card__nr u-text-body-large">05</div><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-card__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div><div class="service-card__body"><h3 class="service-card__title u-text-headings-small">ALL-ON-X</h3></div></div></div><!--]--></div><!--]--></div></div><div class="u-bg-primary"><div class="container container--size-default"><!--[--><div class="services-list-item-grid"><!--[--><div class="services-list-item-grid__item service-list-item" style="--delay:0s;"><div class="service-list-item__nr u-text-body-large">06</div><h3 class="service-list-item__title u-text-headings-small">Sedation and anaesthesia</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.3s;"><div class="service-list-item__nr u-text-body-large">07</div><h3 class="service-list-item__title u-text-headings-small">Therapy</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.6s;"><div class="service-list-item__nr u-text-body-large">08</div><h3 class="service-list-item__title u-text-headings-small">Endodontics</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.8999999999999999s;"><div class="service-list-item__nr u-text-body-large">09</div><h3 class="service-list-item__title u-text-headings-small">Surgery</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:1.2s;"><div class="service-list-item__nr u-text-body-large">10</div><h3 class="service-list-item__title u-text-headings-small">Aligners</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#1A1A1A" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><!--]--></div><!--]--></div></div></div></div></section>
<section id="team" style="view-timeline:--tl-section-team;"><div class="overlay-section"><div class="team doctor-profile u-bg-secondary"><div class="container container--size-default"><div class="doctor-profile__header"><p class="doctor-profile__eyebrow u-text-body-xsmall">Meet your dentist</p><h2 class="u-text-headings-large">Dedicated Dental Care <span class="u-text-wine">You Can Trust.</span></h2></div><div class="doctor-profile__grid"><div class="doctor-profile__portrait"><div class="doctor-profile__portrait-frame" role="img" aria-label="Portrait placeholder for Dr. Kriti Shrivastava"><span class="doctor-profile__initials" aria-hidden="true">KS</span><span class="doctor-profile__portrait-note" aria-hidden="true">Portrait placeholder</span></div></div><article class="doctor-profile__content"><p class="doctor-profile__eyebrow u-text-body-xsmall">Your dentist in Nashik</p><h3 class="doctor-profile__name">Dr. Kriti Shrivastava</h3><p class="doctor-profile__role u-text-body-large">Chief Dental Surgeon</p><p class="doctor-profile__reg u-text-body-xsmall">Registration No. 1977</p><div class="doctor-profile__body u-text-body-medium"><p>Dr. Kriti Shrivastava leads Shrivastava Dental Clinic with a calm, precise approach to everyday dentistry and complex treatment planning.</p><p>She takes time to understand your concerns, explain each step clearly, and use modern diagnostics with gentle techniques so every visit feels comfortable and predictable.</p></div><ul class="doctor-profile__facts"><li class="doctor-profile__chip u-text-body-xsmall">Personalized care</li><li class="doctor-profile__chip u-text-body-xsmall">Gentle techniques</li><li class="doctor-profile__chip u-text-body-xsmall">Modern diagnostics</li></ul><div class="doctor-profile__actions"><a class="button button--type-primary" href="tel:7796376170"><div class="button__text u-text-body-button">Book an appointment</div></a><a class="doctor-profile__link u-text-body-button" href="#services">Explore services</a></div></article></div></div></div></div></section><section id="faq" style="view-timeline:--tl-section-faq;"><div class="faq u-bg-secondary"><div class="container container--size-default"><!--[--><div class="faq__header"><h2 class="u-text-headings-large">Before you start, you might want to <span class="u-text-wine">know more.</span></h2></div><div class="faq__body"><div class="faq-categories"><!--[--><details class="details details--size-large faq-category" open="" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Diagnostics and treatment</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" open="" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How long does the first complex diagnostic appointment take?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p style="text-align: left;">The first appointment lasts for about 30 minutes.&nbsp;</p><p style="text-align: left;">The second appointment&nbsp;—&nbsp;presentation of the treatment plan&nbsp;—&nbsp;takes up to 30 minutes.&nbsp;</p><p style="text-align: left;">If you live outside Latvia or are often travelling, the presentation appointment can be conducted remotely (on the Zoom platform), while we will help you plan your treatment appointments compactly.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What examinations are performed during complex diagnostics?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><ul class="list-bullet"><li class="" style="text-align: left;" value="1">Visual examination of the oral cavity and teeth&nbsp;</li><li class="" style="text-align: left;" value="2">Digital X-rays&nbsp;</li><li class="" style="text-align: left;" value="3">Intraoral 3D scanning (3Shape, iTero Lumina)&nbsp;</li><li class="" style="text-align: left;" value="4">3D computed tomography (CT)&nbsp;</li><li class="" style="text-align: left;" value="5">Diagnostic photo protocol</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What is DSD — digital smile design?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>DSD is a method that allows you to envision the final result before treatment.&nbsp;It helps you find the perfect shape and proportions for your smile highlighting your individuality, harmonising your smile with your facial features, and making you feel more confident.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.30000000000000004s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How long will it take for my treatment plan to be prepared?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>On average, it will take five days. The precise length of time depends on the state of your oral cavity and treatment aims.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.4s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What is a treatment plan coordinator?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p style="text-align: left;">A treatment plan coordinator is a specialist who takes care to ensure that your treatment experience is clear and convenient.<br></p><p style="text-align: left;">The coordinator will help you:</p><ul class="list-bullet"><li class="" style="text-align: left;" value="1">understand the treatment plan and expenditures&nbsp;</li><li class="" style="text-align: left;" value="2">coordinate appointment times&nbsp;</li><li class="" style="text-align: left;" value="3">answer practical questions&nbsp;</li><li class="" style="text-align: left;" value="4">ensure that you can concentrate on the most important things&nbsp;—&nbsp;your health and smile</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.5s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Can I receive my appointment data?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p style="text-align: left;">Yes, we send the digital X-ray images to your e-mail address. But it is not technically possible to send intraoral images.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.6000000000000001s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Is it possible to receive a printed treatment plan?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, after the plan has been prepared, you'll receive its financial section in printed form.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Services and prices</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">How much do your services cost?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Prices depend on the type and complexity of the treatment.&nbsp;The exact cost can only be determined after a complex diagnosis.&nbsp;</p><p>You can find the prices of the most popular services in our&nbsp;Price List.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What solutions do you offer?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><ul class="list-bullet"><li class="" style="text-align: left;" value="1">Exclusive veneers&nbsp;</li><li class="" style="text-align: left;" value="2">Dental implants (Straumann, Neodent)&nbsp;</li><li class="" style="text-align: left;" value="3">Aligners (transparent crowns)&nbsp;</li><li class="" style="text-align: left;" value="4">All-ON-X solutions for multiple tooth loss&nbsp;</li><li class="" style="text-align: left;" value="5">Professional hygiene and whitening (FLASH system)&nbsp;</li><li class="" style="text-align: left;" value="6">Aesthetic and therapeutic dentistry&nbsp;</li><li class="" style="text-align: left;" value="7">Endodontics (root canal treatment under microscope control)&nbsp;</li><li class="" style="" value="8">Dental surgery</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">What is All-ON-X?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>All-ON-X is a unique method involving:</p><p>Extraction of damaged teeth in one operation&nbsp;</p><p>Insertion of 4 or 6 implants&nbsp;</p><p>Immediate loading of a fixed prosthesis&nbsp;</p><p>The treatment is usually performed under sedation.&nbsp;You fall asleep and wake up with a new smile.&nbsp;</p><p>This is the ideal method for patients with multiple tooth loss or who need a complete set of dentures.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Comfort and safety</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Is treatment possible with no fear or discomfort? </div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Yes, we offer treatment with sedation or general anaesthesia.&nbsp;Our leading anaesthesiologist will make sure that you are safe and comfortable so you feel calm and at peace.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Is dental hygiene painful?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>No. We use state-of-the-art —&nbsp;<strong>EMS AIRFLOWÂ® Prophylaxis Master</strong>.&nbsp;It is a safe, precise and comfortable method that removes plaque, pigments and tartar without damaging the tooth tissue.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.30000000000000004s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">About the clinic</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Why are you called a studio, not a clinic? </div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>We want to change the perception of dentistry.&nbsp;A studio is a modern, beautiful and cosy space, with a peaceful atmosphere.&nbsp;It is an environment where smiles are created as work of arts — with science, technology and care for people.&nbsp;</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Where is LAVA Dental Studio? </div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>You can find us at AusekÄ¼a Street 14 (1st floor), Riga.&nbsp;Parking in zone B is available, which we pay for while you are in our studio.&nbsp;</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Is parking available for clients? </div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Although don't have a private car park, we pay for parking in zone B next door.&nbsp;Just inform our team and we'll take care of the rest.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><!--]--></div></div><!--]--></div></div></section>
<section id="contacts" style="view-timeline:--tl-section-contacts;"><div class="contacts u-bg-secondary"><div class="container container--size-default"><!--[--><div class="contacts__header"><h2 class="u-text-headings-large">We are <span class="u-text-wine">right here.</span> </h2></div><div class="contacts__body"><div class="image-info-box"><div class="image-info-box__item image-info-box__item--aside"><!--[--><img width="740" height="627" data-nuxt-img="" srcset="/assets/img/1de9caf9aa9f-map.svg 1x, /assets/img/dd2271325196-map.svg 2x" onerror="this.setAttribute('data-error', 1)" class="image image-info-box__image" alt="Map" loading="lazy" src="/assets/img/1de9caf9aa9f-map.svg"><!--]--></div><div class="image-info-box__item image-info-box__item--main"><div class="scroll-box"><div class="vertical-scroll-progress-bar vertical-scroll-progress-bar--theme-primary scroll-box__progress-bar"></div><div class="scroll-box__header"><p class="u-text-body-large">Conveniently located to make your appointment even easier. With easy access for people with mobility impairments. </p><!----></div><div class="scroll-box__body"><!--[--><!--[--><div class="u-wysiwyg"><p>Our studio is located at AusekÄ¼a Street 14, where there are parking spaces in Zone B. We will pay for your parking while you are at LAVA dental.</p>
</div><!--]--><!--]--></div></div></div><!----></div></div><div class="contacts__footer"><img width="1290" height="590" data-nuxt-img="" sizes="(max-width: 639px) 100vw, (max-width: 1279px) 100vw, (max-width: 1349px) 100vw, 1290px" srcset="/assets/img/6be9b9a04821-location.avif 320w, /assets/img/936863dc2c1a-location.avif 640w, /assets/img/9f7348037191-location.avif 1280w, /assets/img/99bea6f7b10f-location.avif 1290w, /assets/img/4bbb139df2cb-location.avif 2560w, /assets/img/b86bd4d1f5a0-location.avif 2580w" onerror="this.setAttribute('data-error', 1)" class="image" alt="LAVA Dental Studio" loading="lazy" src="/assets/img/b86bd4d1f5a0-location.avif"></div><!--]--></div></div></section><!--]--></div></main>
